def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    rich_threat = 0
    urgent_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 200:
                rich_threat += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if isinstance(prev, dict) else None
            if bid is not None:
                prev_bids.append(float(bid))

    if budget <= 0:
        return 0.0

    slots = max(1, int(supply // WATER_REQ))
    pressure = len(alive_opponents) + 1 - slots
    highest_prev = max(prev_bids) if prev_bids else 0.0

    if hp <= 2 or no_water >= 2:
        target = max(0.92 * DAILY_SALARY, highest_prev + 2.0)
    elif hp <= 4 or no_water >= 1:
        target = max(0.78 * DAILY_SALARY, highest_prev + 1.0 if highest_prev > 0 else 0.78 * DAILY_SALARY)
    else:
        if slots >= len(alive_opponents) + 1:
            target = 0.18 * DAILY_SALARY
        elif pressure <= 1:
            target = 0.38 * DAILY_SALARY
        else:
            target = 0.52 * DAILY_SALARY

        if highest_prev >= 90:
            target = min(target, 0.34 * DAILY_SALARY)
        elif highest_prev >= 75:
            target = min(max(target, 0.45 * DAILY_SALARY), 0.58 * DAILY_SALARY)
        elif highest_prev > 0:
            target = max(target, min(highest_prev + 1.25, 0.68 * DAILY_SALARY))

    if rich_threat >= 2 and hp > 4 and no_water == 0:
        target *= 0.9
    if urgent_opp >= 2 and hp > 4 and no_water == 0:
        target *= 0.92

    if day >= 8 and hp > 5 and no_water == 0:
        target *= 0.9

    min_safe = 0.0
    if hp <= 4 or no_water >= 1:
        min_safe = 0.45 * DAILY_SALARY

    bid = max(min_safe, target)
    bid = min(budget, bid)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

