def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If no opponents, take safe moderate bid
    if not alive_opps:
        target = DAILY_SALARY * 0.35
        return float(min(my_status['budget'], target))

    # Read yesterday bids from previous_trace
    yesterday_bids = []
    yesterday_pressures = []  # (bid, hp_after)
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            b = float(prev.get('bid'))
            yesterday_bids.append(b)
            yesterday_pressures.append((b, prev.get('hp_after', None)))

    # Estimate opponent aggressiveness
    bob_like_bid = None
    # If Bob exists, use his yesterday bid as anchor
    if 'Bob' in opponents_status and opponents_status['Bob'].get('alive', False):
        prev = opponents_status['Bob'].get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bob_like_bid = float(prev.get('bid'))

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
    else:
        highest_prev_bid = 0.0

    # Determine how many water units are likely available; use to scale bid.
    # supply is float; ensure integer indices not needed, but compute units safely.
    est_units = int(supply // WATER_REQ) if WATER_REQ > 0 else 0
    if est_units < 1:
        est_units = 1

    # Thresholds derived from observed meta outcome: Bob bids high and survives.
    # We try to beat the likely winner when my HP is healthy.
    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    # Base bid level
    if bob_like_bid is not None:
        # If Bob was bidding very high, we either match+slightly or conserve.
        if bob_like_bid >= DAILY_SALARY * 0.55:
            if my_hp >= 5:
                target = bob_like_bid * 1.03
            else:
                target = bob_like_bid * 1.10
        else:
            # Bob wasn't too aggressive; still bid enough to avoid being outbid by highest.
            target = max(highest_prev_bid * 1.02, DAILY_SALARY * 0.45)
    else:
        # No Bob anchor: use highest previous bid.
        if highest_prev_bid >= DAILY_SALARY * 0.6:
            if my_hp >= 5:
                target = highest_prev_bid * 1.02
            else:
                target = highest_prev_bid * 1.08
        else:
            target = max(highest_prev_bid * 1.05, DAILY_SALARY * 0.5)

    # Scale by expected scarcity: lower supply => higher competition => bid a bit more.
    # supply in [15,25]
    scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    target = target * (1.0 + 0.12 * scarcity)

    # If my HP is low, prioritize survival; if high, avoid waste.
    if my_hp <= 2.0:
        target = max(target, DAILY_SALARY * 0.85)
    elif my_hp <= 4.0:
        target = max(target, DAILY_SALARY * 0.65)
    else:
        # keep some budget for future days
        target = min(target, DAILY_SALARY * 0.75 + 0.05 * highest_prev_bid)

    # Convert target to a feasible bid
    # Also cap to not exceed budget
    target = float(min(my_budget, target))

    # Ensure non-negative
    if target < 0.0:
        target = 0.0

    return target
